private static void helpTestUpdateCache(String fullTableName, int[] expectedRPCs, boolean skipUpsertForIndexes) throws Exception {
    String tableName = SchemaUtil.getTableNameFromFullName(fullTableName);
    String schemaName = SchemaUtil.getSchemaNameFromFullName(fullTableName);
    String selectSql = "SELECT * FROM " + fullTableName;
    // use a spyed ConnectionQueryServices so we can verify calls to getTable
    ConnectionQueryServices connectionQueryServices = Mockito.spy(driver.getConnectionQueryServices(getUrl(), PropertiesUtil.deepCopy(TEST_PROPERTIES)));
    Properties props = new Properties();
    props.putAll(PhoenixEmbeddedDriver.DEFAULT_PROPS.asMap());
    Connection conn = connectionQueryServices.connect(getUrl(), props);
    try {
        conn.setAutoCommit(false);
        if (!skipUpsertForIndexes) {
            String upsert = "UPSERT INTO " + fullTableName + "(varchar_pk, char_pk, int_pk, long_pk, decimal_pk, date_pk) VALUES(?, ?, ?, ?, ?, ?)";
            PreparedStatement stmt = conn.prepareStatement(upsert);
            // upsert three rows
            for (int i = 0; i < 3; i++) {
                TestUtil.setRowKeyColumns(stmt, i);
                stmt.execute();
            }
            conn.commit();
            int numUpsertRpcs = expectedRPCs[0];
            // verify only 0 or 1 rpc to fetch table metadata,
            verify(connectionQueryServices, times(numUpsertRpcs)).getTable((PName) isNull(), eq(PVarchar.INSTANCE.toBytes(schemaName)), eq(PVarchar.INSTANCE.toBytes(tableName)), anyLong(), anyLong());
            reset(connectionQueryServices);
        }
        validateSelectRowKeyCols(conn, selectSql, skipUpsertForIndexes);
        validateSelectRowKeyCols(conn, selectSql, skipUpsertForIndexes);
        validateSelectRowKeyCols(conn, selectSql, skipUpsertForIndexes);
        // for non-transactional tables without a scn : verify one rpc to getTable occurs *per* query
        // for non-transactional tables with a scn : verify *only* one rpc occurs
        // for transactional tables : verify *only* one rpc occurs
        // for non-transactional, system tables : verify no rpc occurs
        int numRpcs = skipUpsertForIndexes ? expectedRPCs[0] : expectedRPCs[1];
        verify(connectionQueryServices, times(numRpcs)).getTable((PName) isNull(), eq(PVarchar.INSTANCE.toBytes(schemaName)), eq(PVarchar.INSTANCE.toBytes(tableName)), anyLong(), anyLong());
    } finally {
        conn.close();
    }
}

@Test
public void testIndexPriorityWritesToIndexHandler() throws Exception {
    RpcScheduler mock = Mockito.mock(RpcScheduler.class);
    PriorityFunction qosFunction = Mockito.mock(PriorityFunction.class);
    Abortable abortable = new AbortServer();
    PhoenixRpcScheduler scheduler = new PhoenixRpcScheduler(conf, mock, 200, 250, qosFunction, abortable);
    BalancedQueueRpcExecutor executor = new BalancedQueueRpcExecutor("test-queue", 1, 1, qosFunction, conf, abortable);
    scheduler.setIndexExecutorForTesting(executor);
    dispatchCallWithPriority(scheduler, 200);
    List<BlockingQueue<CallRunner>> queues = executor.getQueues();
    assertEquals(1, queues.size());
    BlockingQueue<CallRunner> queue = queues.get(0);
    queue.poll(20, TimeUnit.SECONDS);
    // try again, this time we tweak the ranges we support
    scheduler = new PhoenixRpcScheduler(conf, mock, 101, 110, qosFunction, abortable);
    scheduler.setIndexExecutorForTesting(executor);
    dispatchCallWithPriority(scheduler, 101);
    queue.poll(20, TimeUnit.SECONDS);
    Mockito.verify(mock, Mockito.times(2)).init(Mockito.any(Context.class));
    scheduler.stop();
    executor.stop();
}

